      STAY = {c:'#d9dcdc', lk:0.9}, RED = {c:'#a81010', glow:'#ff2a14', gk:2.4}, POLE = '#7d8286', LAMPH = {c:'#efe2c0', glow:'#ffcf8a', gk:1.6};
